WITH with_last AS (SELECT s.id, s.product_name, s.category, s.brand, s.price, s.launch_date, s.tags, s.supplier_id, latest.quantity, latest.order_item_unit_price FROM products s LEFT JOIN LATERAL (SELECT c.quantity, c.unit_price AS order_item_unit_price FROM order_items c WHERE c.product_id = s.id ORDER BY c.unit_price DESC, c.id DESC LIMIT 1) latest ON TRUE), metrics AS (SELECT *, SUM(order_item_unit_price) OVER (ORDER BY launch_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_order_item_unit_price, SUM(price) OVER (PARTITION BY supplier_id ORDER BY launch_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_price FROM with_last), kept AS (SELECT s.* FROM metrics s WHERE EXISTS (SELECT 1 FROM order_items c WHERE c.product_id = s.id AND c.order_id IN (3, 21, 27))), eligible AS (SELECT s.* FROM kept s WHERE EXISTS (SELECT 1 FROM inventory c WHERE c.product_id = s.id AND c.last_restock < s.launch_date)) SELECT id, brand, tags, supplier_id, running_order_item_unit_price FROM eligible ORDER BY brand DESC;
